public struct FfiConverterTypeRovenueCore: FfiConverter {
    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = RovenueCore

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RovenueCore {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if (ptr == nil) {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: RovenueCore, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> RovenueCore {
        return RovenueCore(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: RovenueCore) -> UnsafeMutableRawPointer {
        return value.pointer
    }
}


public func FfiConverterTypeRovenueCore_lift(_ pointer: UnsafeMutableRawPointer) throws -> RovenueCore {
    return try FfiConverterTypeRovenueCore.lift(pointer)
}

public func FfiConverterTypeRovenueCore_lower(_ value: RovenueCore) -> UnsafeMutableRawPointer {
    return FfiConverterTypeRovenueCore.lower(value)
}


