public enum DraftRefresh {
    
    case notModified
    case changed(funnelJson: String, etag: String)
    case blocked(issues: [DraftIssue], etag: String)
    case gone
}

public struct FfiConverterTypeDraftRefresh: FfiConverterRustBuffer {
    typealias SwiftType = DraftRefresh

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DraftRefresh {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .notModified
        
        case 2: return .changed(
            funnelJson: try FfiConverterString.read(from: &buf), 
            etag: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .blocked(
            issues: try FfiConverterSequenceTypeDraftIssue.read(from: &buf), 
            etag: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .gone
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DraftRefresh, into buf: inout [UInt8]) {
        switch value {
        
        
        case .notModified:
            writeInt(&buf, Int32(1))
        
        
        case let .changed(funnelJson,etag):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(funnelJson, into: &buf)
            FfiConverterString.write(etag, into: &buf)
            
        
        case let .blocked(issues,etag):
            writeInt(&buf, Int32(3))
            FfiConverterSequenceTypeDraftIssue.write(issues, into: &buf)
            FfiConverterString.write(etag, into: &buf)
            
        
        case .gone:
            writeInt(&buf, Int32(4))
        
        }
    }
}


public func FfiConverterTypeDraftRefresh_lift(_ buf: RustBuffer) throws -> DraftRefresh {
    return try FfiConverterTypeDraftRefresh.lift(buf)
}

